        long long cnt = 0;
        if (d == 0) { if (B >= 1 && B <= Y) cnt = 1; }
        else { if (B-d >= 1) cnt++; if (B+d <= Y) cnt++; }
        if (d <= maxD) f2[d] = cnt;
    }
    for (long long d = 0; d <= Z+C; d++) {
        long long cnt = 0;
        if (d == 0) { if (C >= 1 && C <= Z) cnt = 1; }
        else { if (C-d >= 1) cnt++; if (C+d <= Z) cnt++; }
        if (d <= maxD) f3[d] = cnt;
    }

    // Convolve f1 and f2
    for (int i = 0; i <= maxD; i++)
