typedef long long ll;

/*
We need counts of cubes in an X*Y*Z box whose Manhattan distance
from origin cube (A,B,C) equals d modulo N.

Coordinates are 1-based:
x in [1..X], y in [1..Y], z in [1..Z]
distance = |x-A| + |y-B| + |z-C|

Let fx[i] be number of x with |x-A| = i, similarly fy, fz.
Then number of cubes at exact distance d is convolution:
cnt[d] = sum_{i+j+k=d} fx[i] fy[j] fz[k]

Ranges are at most X-1, Y-1, Z-1. We compute by O(XY + ...?) using
two convolutions by direct loops, which is fine for moderate constraints.
Since the statement provided here omits constraints, we use the standard
O((X+Y+Z)^2) style via pair convolution:
g[s] = sum_i fx[i] fy[s-i]
cnt[d] = sum_s g[s] fz[d-s]

Finally accumulate cnt[d] into ans[d % N].
*/

static ll *build_axis_counts(int L, int P, int *maxd_out) {
    int left = P - 1;
    int right = L - P;
    int maxd = left > right ? left : right;
    ll *f = (ll *)calloc((size_t)maxd + 1, sizeof(ll));
    if (!f) exit(1);

    f[0] = 1;
    int mn = left < right ? left : right;
    int mx = left > right ? left : right;

    for (int d = 1; d <= mn; d++) f[d] = 2;
    for (int d = mn + 1; d <= mx; d++) f[d] = 1;

    *maxd_out = maxd;
    return f;
}

int main(void) {
    int X, Y, Z, A, B, C, N;
    if (scanf("%d %d %d %d %d %d %d", &X, &Y, &Z, &A, &B, &C, &N) != 7) {
        return 0;
    }

    int dx, dy, dz;
    ll *fx = build_axis_counts(X, A, &dx);
    ll *fy = build_axis_counts(Y, B, &dy);
    ll *fz = build_axis_counts(Z, C, &dz);

    int dxy = dx + dy;
    ll *g = (ll *)calloc((size_t)dxy + 1, sizeof(ll));
    if (!g) return 0;

    for (int i = 0; i <= dx; i++) {
        if (!fx[i]) continue;
        for (int j = 0; j <= dy; j++) {
            if (!fy[j]) continue;
            g[i + j] += fx[i] * fy[j];
        }
    }

    int dmax = dxy + dz;
    ll *ans = (ll *)calloc((size_t)N, sizeof(ll));
    if (!ans) return 0;

    for (int s = 0; s <= dxy; s++) {
        if (!g[s]) continue;
        for (int k = 0; k <= dz; k++) {
            if (!fz[k]) continue;
            ans[(s + k) % N] += g[s] * fz[k];
        }
    }

    for (int i = 0; i < N; i++) {
        if (i) printf(" ");
        printf("%lld", ans[i]);
    }
    printf("\n");

    free(fx);
    free(fy);
    free(fz);
    free(g);
    free(ans);
    return 0;
}

