    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int X = Integer.parseInt(st.nextToken());
        int Y = Integer.parseInt(st.nextToken());
        int Z = Integer.parseInt(st.nextToken());
        int N = Integer.parseInt(st.nextToken());
        st = new StringTokenizer(br.readLine());
        int A = Integer.parseInt(st.nextToken());
        int B = Integer.parseInt(st.nextToken());
        int C = Integer.parseInt(st.nextToken());

        int maxD = (X + Y + Z);
        long[] cx = new long[maxD + 1];
        long[] cy = new long[maxD + 1];
        long[] cz = new long[maxD + 1];

        for (int x = 1; x <= X; x++) { int d = Math.abs(x - A); if (d <= maxD) cx[d]++; }
        for (int y = 1; y <= Y; y++) { int d = Math.abs(y - B); if (d <= maxD) cy[d]++; }
        for (int z = 1; z <= Z; z++) { int d = Math.abs(z - C); if (d <= maxD) cz[d]++; }

        long[] cyz = new long[maxD + 1];
        for (int d2 = 0; d2 <= maxD; d2++) if (cy[d2] > 0)
            for (int d3 = 0; d2 + d3 <= maxD; d3++) if (cz[d3] > 0)
                cyz[d2 + d3] += cy[d2] * cz[d3];

        long[] color = new long[N];
        for (int d1 = 0; d1 <= maxD; d1++) if (cx[d1] > 0)
            for (int d = d1; d <= maxD; d++) if (cyz[d - d1] > 0)
                color[d % N] += cx[d1] * cyz[d - d1];

        StringBuilder sb = new StringBuilder();
        for (int k = 0; k < N; k++) sb.append(color[k]).append("\n");
        System.out.print(sb);
    }
}

import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        long nextLong() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            long sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            long val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }

    static long[] count1D(int len, int pos, int n) {
        long[] cnt = new long[n];
        long left = pos - 1L;
        long right = len - pos;

        cnt[0] = 1; // distance 0

        for (int r = 0; r < n; r++) {
            cnt[r] += countPositiveDistancesWithResidue(left, r, n);
            cnt[r] += countPositiveDistancesWithResidue(right, r, n);
        }
        return cnt;
    }

    static long countPositiveDistancesWithResidue(long limit, int residue, int n) {
        if (limit <= 0) return 0;
        long first = residue == 0 ? n : residue;
        if (first > limit) return 0;
        return (limit - first) / n + 1;
    }

    static long[] circularConvolution(long[] a, long[] b, int n) {
        long[] res = new long[n];
        for (int i = 0; i < n; i++) {
            if (a[i] == 0) continue;
            for (int j = 0; j < n; j++) {
                res[(i + j) % n] += a[i] * b[j];
            }
        }
        return res;
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();

        int X = (int) fs.nextLong();
        int Y = (int) fs.nextLong();
        int Z = (int) fs.nextLong();
        int A = (int) fs.nextLong();
        int B = (int) fs.nextLong();
        int C = (int) fs.nextLong();
        int N = (int) fs.nextLong();

        long[] cx = count1D(X, A, N);
        long[] cy = count1D(Y, B, N);
        long[] cz = count1D(Z, C, N);

        long[] xy = circularConvolution(cx, cy, N);
        long[] ans = circularConvolution(xy, cz, N);

        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < N; i++) {
            if (i > 0) sb.append('\n');
            sb.append(ans[i]);
        }
        System.out.print(sb.toString());
    }
}

