int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int64 X, Y, Z, A, B, C, N;
    cin >> X >> Y >> Z >> A >> B >> C >> N;

    vector<int64> xcnt(X), ycnt(Y), zcnt(Z);
    for (int64 i = 0; i < X; i++) xcnt[abs(i - A)]++;
    for (int64 i = 0; i < Y; i++) ycnt[abs(i - B)]++;
    for (int64 i = 0; i < Z; i++) zcnt[abs(i - C)]++;

    vector<int64> res(N, 0);

    // For each possible dx, dy, we compute contribution
    for (int64 dx = 0; dx < X; dx++) {
        if (xcnt[dx] == 0) continue;
        for (int64 dy = 0; dy < Y; dy++) {
            if (ycnt[dy] == 0) continue;
            int64 base = dx + dy;
            // For each possible dz, remainder = (base + dz) % N
            for (int64 dz = 0; dz < Z; dz++) {
                if (zcnt[dz] == 0) continue;
                int64 color = (base + dz) % N;
                res[color] += xcnt[dx] * ycnt[dy] * zcnt[dz];
            }
        }
    }

    for (int64 i = 0; i < N; i++) {
        cout << res[i] << (i + 1 == N ? '\n' : ' ');
    }

    return 0;
}

