int main(){
    long long X, Y, Z, N, A, B, C;
    cin >> X >> Y >> Z >> N >> A >> B >> C;

    // For each dimension, count[k] = number of positions with |pos - origin| = k
    auto makeCnt = [](long long L, long long origin) -> vector<long long> {
        long long maxD = max(origin - 1, L - origin);
        vector<long long> cnt(maxD + 1, 0);
        for(long long k = 0; k <= maxD; k++){
            long long c = 0;
            if(k == 0) c = 1;
            else {
                if(origin + k >= 1 && origin + k <= L) c++;
                if(origin - k >= 1 && origin - k <= L) c++;
            }
            cnt[k] = c;
        }
        return cnt;
    };

    vector<long long> cx = makeCnt(X, A);
    vector<long long> cy = makeCnt(Y, B);
    vector<long long> cz = makeCnt(Z, C);

    // Convolve cx and cy
    int sxy = cx.size() + cy.size() - 1;
    vector<long long> cxy(sxy, 0);
    for(int i = 0; i < (int)cx.size(); i++)
        for(int j = 0; j < (int)cy.size(); j++)
            cxy[i+j] += cx[i]*cy[j];

    int stot = cxy.size() + cz.size() - 1;
    vector<long long> ctot(stot, 0);
    for(int i = 0; i < (int)cxy.size(); i++)
        for(int j = 0; j < (int)cz.size(); j++)
            ctot[i+j] += cxy[i]*cz[j];

    vector<long long> ans(N, 0);
    for(int d = 0; d < (int)ctot.size(); d++){
        ans[d % N] += ctot[d];
    }

    for(int i = 0; i < N; i++){
        cout << ans[i] << "\n";
    }

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

using int64 = long long;

// Count pairs (u,v) with 0<=u<X, 0<=v<Y and u+v = s
static vector<int64> pairSumCounts(int X, int Y) {
    int maxS = X + Y - 2;
    vector<int64> cnt(maxS + 1, 0);
    for (int s = 0; s <= maxS; ++s) {
        int L = max(0, s - (Y - 1));
        int R = min(X - 1, s);
        if (L <= R) cnt[s] = (int64)R - L + 1;
    }
    return cnt;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int X, Y, Z, N;
    int A, B, C;
    cin >> X >> Y >> Z >> N;
    cin >> A >> B >> C;

    // Distances along each axis:
    // dx in [0..A-1] appears once, dx in [1..X-A] appears once
    // so count of nonnegative dx values:
    // cntX[0]=1, cntX[t]= (t<=A-1) + (t<=X-A) for t>=1
    int maxDx = max(A - 1, X - A);
    int maxDy = max(B - 1, Y - B);
    int maxDz = max(C - 1, Z - C);

    vector<int64> cx(maxDx + 1, 0), cy(maxDy + 1, 0), cz(maxDz + 1, 0);

    cx[0] = 1;
    for (int t = 1; t <= maxDx; ++t) {
        if (t <= A - 1) cx[t]++;
        if (t <= X - A) cx[t]++;
    }

    cy[0] = 1;
    for (int t = 1; t <= maxDy; ++t) {
        if (t <= B - 1) cy[t]++;
        if (t <= Y - B) cy[t]++;
    }

    cz[0] = 1;
    for (int t = 1; t <= maxDz; ++t) {
        if (t <= C - 1) cz[t]++;
        if (t <= Z - C) cz[t]++;
    }

    // Convolve cx and cy naively in O((X+Y)^2) via exact formula for pair sums
    // We can do better by observing cx,cy come from two intervals.
    // Equivalent to counting sums of four combinations:
    // x-left [0..A-1], x-right [1..X-A], y-left [0..B-1], y-right [1..Y-B]
    // Easier: build exact counts for dx+dy by direct convolution since sizes are small enough
    // for typical constraints; but to stay safe, use formula from interval sums.

    // Build counts of dx+dy from cx, cy by O(maxDx*maxDy) would be too much if large.
    // Instead represent cx = I[0..A-1] + I[1..X-A], similarly for cy.
    auto addRect = [&](vector<int64>& target, int L1, int R1, int L2, int R2, int coef = 1) {
        if (L1 > R1 || L2 > R2) return;
        int len1 = R1 - L1 + 1;
        int len2 = R2 - L2 + 1;
        auto base = pairSumCounts(len1, len2); // sums for [0..len1-1] + [0..len2-1]
        int shift = L1 + L2;
        if ((int)target.size() < shift + (int)base.size()) target.resize(shift + base.size(), 0);
        for (int i = 0; i < (int)base.size(); ++i) target[shift + i] += coef * base[i];
    };

    vector<int64> cxy;
    // cx parts: [0..A-1], [1..X-A]
    // cy parts: [0..B-1], [1..Y-B]
    addRect(cxy, 0, A - 1, 0, B - 1);
    addRect(cxy, 0, A - 1, 1, Y - B);
    addRect(cxy, 1, X - A, 0, B - 1);
    addRect(cxy, 1, X - A, 1, Y - B);

    // Now combine with z similarly
    vector<int64> distCounts;
    auto addWithZ = [&](int Lz, int Rz) {
        if (Lz > Rz) return;
        int lenz = Rz - Lz + 1;
        for (int s = 0; s < (int)cxy.size(); ++s) {
            if (cxy[s] == 0) continue;
            if ((int)distCounts.size() < s + Lz + lenz) distCounts.resize(s + Lz + lenz, 0);
            for (int z = 0; z < lenz; ++z) {
                distCounts[s + Lz + z] += cxy[s];
            }
        }
    };

    // The above inner loop may be large; do difference array instead.
    distCounts.clear();
    int maxS = (int)cxy.size() - 1 + max(C - 1, Z - C);
    distCounts.assign(maxS + 2, 0);

    auto rangeAddZ = [&](int Lz, int Rz) {
        if (Lz > Rz) return;
        for (int s = 0; s < (int)cxy.size(); ++s) {
            if (cxy[s] == 0) continue;
            distCounts[s + Lz] += cxy[s];
            distCounts[s + Rz + 1] -= cxy[s];
        }
    };

    rangeAddZ(0, C - 1);
    rangeAddZ(1, Z - C);

    for (int i = 1; i < (int)distCounts.size(); ++i) distCounts[i] += distCounts[i - 1];
    distCounts.pop_back();

    vector<int64> ans(N, 0);
    for (int d = 0; d < (int)distCounts.size(); ++d) {
        ans[d % N] += distCounts[d];
    }

    for (int i = 0; i < N; ++i) {
        if (i) cout << ' ';
        cout << ans[i];
    }
    cout << '\n';
    return 0;
}
